 const options=p=>{const prior=choices.get(p.id)||{};const a=accessories.find(a=>a.id===state.storage);const allowed=a?p.widths.filter(w=>compatibility(p,w,a).ok):p.widths;const width=allowed.includes(prior.width)?prior.width:allowed.includes(Number(state.width))?Number(state.width):(p.kind==='door'&&allowed.includes(24)?24:allowed[0])||p.widths[0];const result={width,finish:state.finish,style:state.style,storage:state.storage||prior.storage||'',forceStorage:!!state.storage};choices.set(p.id,{width,storage:result.storage});return result;};
