 let config=blank(),project=[],contact={},helpOnly=false,selectedTypes=[],cabinetDrafts={};let solution=savedPlaceholder();let standalone=[];let lastBundleKey="";function savedPlaceholder(){return {path:'',needs:[]};}let halted=false;let saved=read(key,null);if(saved){const removeIncludedShelves=value=>{if(!value||typeof value!=='object')return;for(const [name,child] of Object.entries(value)){if(name==='accessories'&&Array.isArray(child))value[name]=child.filter(id=>id!=='shelves');else if(name==='standalone'&&Array.isArray(child))value[name]=child.filter(item=>item.accessory!=='shelves');else removeIncludedShelves(child);}};removeIncludedShelves(saved);}let timer;solution=saved?.solution||solution;standalone=Array.isArray(saved?.standalone)?saved.standalone:[];let flowNotice="";let removedCabinet=null;let removalMessage="";
 const save=()=>{rememberCabinet();const ok=write(key,{config,project,contact,helpOnly,selectedTypes,cabinetDrafts,solution,standalone,updated:new Date().toISOString()});if(!ok&&!halted){halted=true;$('#configuration-error').hidden=false;$('#configuration-error').textContent='Browser storage is unavailable. Download your reference before leaving.';}updateSummary();};
 const signature=c=>JSON.stringify(['product','width','depth','height','style','finish','doorMaterial','boxMaterial','quantity','accessories','customSize'].map(k=>c?.[k]));
