 const reference=()=>{const entries=project.length?project:(!helpOnly&&config.product)?[config]:[];return 'KABBY HOME — CABINETS & STORAGE REQUEST\n\nKITCHEN PLANNING\n'+Object.entries(solution).filter(([k])=>['path','project','layout','measurements','needs','kitchenArea','roomLength','roomWidth','clearRun'].includes(k)).map(([k,v])=>k+': '+(Array.isArray(v)?v.join(', '):v)).join('\n')+'\n'+estimateContext()+'\n\nSELECTED CABINET TYPES\n'+selectedTypes.map(id=>byId(id)?.name).filter(Boolean).join('\n')+'\n\n'+(helpOnly?'DESIGN HELP REQUEST\n':'')+entries.map((c,i)=>'CABINET '+(i+1)+'\n'+configRows(c).map(([k,v])=>k+': '+v).join('\n')).join('\n\n')+'\n\nSTANDALONE ORGANIZERS (NO NEW CABINET)\n'+standalone.map(a=>accessories.find(x=>x.id===a.accessory)?.name+' · quantity '+a.quantity+'\n'+['width','depth','height','type','obstructions'].map(k=>k+': '+(a[k]||'To discuss')).join('\n')).join('\n\n')+'\n\nPRICING\nCabinet subtotal: Quote required\nFinishes: Quote required\nAccessories: Quote required\nBundle savings: No savings applied\nDesign, delivery and installation: Scope and quote required\nTotal: Quote required\nTax, countertops and appliances excluded unless expressly quoted.\n\nCONTACT\n'+Object.entries(contact).filter(([,v])=>v).map(([k,v])=>k+': '+v).join('\n')+'\n\nNOTES\n'+config.notes+'\n\nIllustrative configuration; factory confirmation required for dimensions, materials and accessory fit. Not a submitted request, approved quote or placed order.';};
