 const rowsHTML=c=>configRows(c).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('');
 function updateSummary(){const p=config.step===0?null:byId(config.product);$('#configuration-summary').innerHTML=`<strong class="quote-total">Quote required</strong><small>Final pricing follows specification review.</small>${removalMessage?'<div class="cabinet-removal-feedback" role="status"><p>'+esc(removalMessage)+'</p>'+(removedCabinet?'<button type="button" id="undo-cabinet-removal">Undo removal</button>':'')+'</div>':''}${p?`<div class="config-mini-preview">${productSvg(p,{width:config.width,depth:config.depth,height:config.height,style:config.style,finish:config.finish})}</div>`:''}${p?'<dl>'+rowsHTML(config)+'</dl>':''}${p&&config.accessories.length?'<div class="selected-storage-previews">'+config.accessories.map(id=>{const a=accessories.find(a=>a.id===id);return '<figure><img src="/kabbie/assets/'+a.image+'" alt="'+esc(a.name)+'" loading="lazy"><figcaption>'+esc(a.name)+'</figcaption></figure>';}).join('')+'</div>':''}${requestKeys().length?'<div class="selected-types-summary"><h3>Cabinet versions · '+requestKeys().length+'</h3><ul>'+requestKeys().map(id=>{const draft=draftFor(id)||{product:id,quantity:1};return '<li><button type="button" class="request-cabinet-switch" data-switch-cabinet="'+id+'" '+(keyOf(config)===id?'aria-current="true"':'')+'><strong>'+esc(cabinetLabel(draft))+'</strong><span>'+(finishes.find(f=>f.id===draft.finish)?.name||'Color not chosen')+' · Qty '+draft.quantity+'</span><small>'+(keyOf(config)===id?'Currently editing':project.some(c=>keyOf(c)===id)?'View or change this version':'Choose this version’s finish')+'</small></button><button type="button" class="remove-plan-cabinet" data-remove-cabinet="'+id+'" aria-label="Remove '+esc(cabinetLabel(draft))+' from plan"><svg aria-hidden="true" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M3 5H17M7 5V3H13V5M5 5L6 17H14L15 5M8 8V14M12 8V14"/></svg>Remove</button></li>';}).join('')+'</ul></div>':''}${helpOnly&&!standalone.length?'<p>Design help requested</p>':''}${standalone.length?'<p><strong>'+standalone.length+' standalone organizer request'+(standalone.length===1?'':'s')+'</strong></p>':''}<p>${project.length} cabinet configuration${project.length===1?'':'s'} in your project</p><details><summary>Cabinets, organizers & savings</summary>${costHTML()}</details>`;const summary=$('#configuration-summary');const items=$('.selected-types-summary',summary);if(items){const image=$('.config-mini-preview',summary);const details=image?.nextElementSibling;if(requestKeys().length>1&&image&&details?.tagName==='DL'){const disclosure=document.createElement('details');disclosure.className='current-cabinet-details';const heading=document.createElement('summary');heading.textContent='Current cabinet details';disclosure.append(heading);image.before(disclosure);disclosure.append(image,details);}const target=$('.current-cabinet-details',summary)||$('.config-mini-preview',summary)||summary.querySelector(':scope > p');if(target)summary.insertBefore(items,target);}$('#undo-cabinet-removal')?.addEventListener('click',undoRemoval);$$('[data-remove-cabinet]').forEach(button=>button.addEventListener('click',()=>removeVersion(button.dataset.removeCabinet)));$$('[data-switch-cabinet]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.switchCabinet;openCabinet(id);if(config.finish)go(2);}));}
 function error(message,selector){const el=$('#configuration-error');el.hidden=false;el.textContent='Stage '+(config.step+1)+' · '+labels[config.step]+': '+message;el.scrollIntoView({block:'nearest',behavior:'smooth'});const field=selector&&$(selector,root);if(field){field.setAttribute('aria-invalid','true');const focusTarget=field.querySelector('[data-material-choice]')||field;focusTarget.focus();}}
