 if(config.step===-5){const item=standalone[solution.editAccessory],a=accessories.find(a=>a.id===item?.accessory);html='<h2 tabindex="-1">Check your existing cabinet.</h2><p>'+esc(a.name)+' · measurements are optional if you need help. Use interior clear space, not outside cabinet dimensions.</p><form id="standalone-details">'+[['width','Interior width (inches)'],['depth','Interior depth (inches)'],['height','Available interior height (inches)']].map(([k,label])=>'<label class="commerce-field">'+label+'<input name="'+k+'" type="number" min="0.1" max="200" step="0.1" value="'+esc(item[k])+'"></label>').join('')+'<label class="commerce-field">Existing cabinet type<select name="type">'+['Not sure','Door base','Drawer base','Wall cabinet','Tall pantry','Corner cabinet'].map(v=>'<option '+(item.type===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label class="commerce-field">Hinges, plumbing or other obstructions<textarea name="obstructions" maxlength="1000" rows="3">'+esc(item.obstructions)+'</textarea></label><label class="commerce-field">Quantity<input name="quantity" type="number" min="1" max="99" required value="'+item.quantity+'"></label><p class="caption">Photos may be attached when you send your email brief. The team confirms availability and internal fit before approval.</p><button class="btn" type="submit">Save Organizer to My Request →</button></form>';}
 root.innerHTML=html+'<button type="button" class="textlink solution-back" id="solution-back">← Back</button>';updateSummary();
